INSERT INTO public.flashcards
  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
(1101, '乎', 'hū', '似乎', 'sì hū', 'ดูเหมือน/ราวกับ', '听了妈妈的话，她似乎明白了很多。', 'ฟังคำแม่แล้ว เธอดูเหมือนจะเข้าใจอะไรหลายอย่าง', 'tīng le mā mā de huà, tā sì hū míng bái le hěn duō'),
(1102, '央', 'yāng', '中央', 'zhōng yāng', 'ตรงกลาง/ศูนย์กลาง', '他在天安门广场中央拍了张照片。', 'เขาถ่ายรูปหนึ่งใบตรงกลางจัตุรัสเทียนอันเหมิน', 'tā zài tiān ān mén guǎng chǎng zhōng yāng pāi le zhāng zhào piàn'),
(1103, '次', 'cì', '一次', 'yí cì', 'หนึ่งครั้ง', '他们又一次冲破了敌人的包围。', 'พวกเขาตีฝ่าวงล้อมของศัตรูออกมาได้อีกครั้ง', 'tā men yòu yí cì chōng pò le dí rén de bāo wéi'),
(1104, '胡', 'hú', '二胡', 'èr hú', 'เอ้อหู (ซอจีน)', '二胡可以拉出美妙的音乐。', 'เอ้อหูสามารถสีออกมาเป็นดนตรีที่ไพเราะ', 'èr hú kě yǐ lā chū měi miào de yīn yuè'),
(1105, '顺', 'shùn', '顺风', 'shùn fēng', 'ตามลม/ราบรื่น', '朋友要去远行，我祝他一路顺风。', 'เพื่อนจะเดินทางไกล ฉันขอให้เขาเดินทางราบรื่น', 'péng yǒu yào qù yuǎn xíng, wǒ zhù tā yí lù shùn fēng'),
(1106, '利', 'lì', '锋利', 'fēng lì', 'คม', '这把刀很锋利，小心切到手。', 'มีดเล่มนี้คมมาก ระวังบาดมือ', 'zhè bǎ dāo hěn fēng lì, xiǎo xīn qiē dào shǒu'),
(1107, '稳', 'wěn', '安稳', 'ān wěn', 'มั่นคง/สงบนิ่ง', '我心里七上八下，坐也坐不安稳。', 'ใจฉันกระวนกระวาย นั่งก็นั่งไม่ติด', 'wǒ xīn lǐ qī shàng bā xià, zuò yě zuò bù ān wěn'),
(1108, '粗', 'cū', '粗细', 'cū xì', 'ความหนาบาง/ขนาด', '竹林里有许多粗细不同的竹子。', 'ในป่าไผ่มีไม้ไผ่ขนาดหนาบางต่างกันมากมาย', 'zhú lín lǐ yǒu xǔ duō cū xì bù tóng de zhú zi'),
(1109, '戏', 'xì', '唱戏', 'chàng xì', 'ร้องงิ้ว', '奶奶年轻的时候最爱听戏唱戏。', 'ตอนสาวๆ คุณย่าชอบฟังงิ้วร้องงิ้วที่สุด', 'nǎi nai nián qīng de shí hòu zuì ài tīng xì chàng xì'),
(1110, '煮', 'zhǔ', '煮熟', 'zhǔ shú', 'ต้มสุก', '鸡蛋煮熟了，可以吃了。', 'ไข่ต้มสุกแล้ว กินได้แล้ว', 'jī dàn zhǔ shú le, kě yǐ chī le'),
(1111, '纷', 'fēn', '纷飞', 'fēn fēi', 'ปลิวว่อน', '寒冬的北国，大雪纷飞，滴水成冰。', 'แดนเหนือในฤดูหนาว หิมะปลิวว่อน น้ำหยดเดียวก็กลายเป็นน้ำแข็ง', 'hán dōng de běi guó, dà xuě fēn fēi, dī shuǐ chéng bīng'),
(1112, '烁', 'shuò', '闪烁', 'shǎn shuò', 'ระยิบระยับ', '晴朗的夜空，星星在天空闪烁。', 'ท้องฟ้ายามค่ำคืนที่แจ่มใส ดวงดาวส่องประกายระยิบระยับ', 'qíng lǎng de yè kōng, xīng xīng zài tiān kōng shǎn shuò'),
(1113, '补', 'bǔ', '补丁', 'bǔ dīng', 'รอยปะ/ปะผ้า', '她在衣服的破洞上打了个补丁。', 'เธอปะรอยขาดบนเสื้อผ้าไว้จุดหนึ่ง', 'tā zài yī fú de pò dòng shàng dǎ le gè bǔ dīng'),
(1114, '哗', 'huá', '喧哗', 'xuān huá', 'ส่งเสียงเอะอะ', '在公共场合不要大声喧哗。', 'ในที่สาธารณะอย่าส่งเสียงเอะอะดังๆ', 'zài gōng gòng chǎng hé bú yào dà shēng xuān huá'),
(1115, '止', 'zhǐ', '止步', 'zhǐ bù', 'หยุดเดิน/หยุดก้าว', '前面的路不能走了，请止步。', 'ทางข้างหน้าเดินต่อไม่ได้แล้ว กรุณาหยุด', 'qián miàn de lù bù néng zǒu le, qǐng zhǐ bù'),
(1116, '娘', 'niáng', '新娘', 'xīn niáng', 'เจ้าสาว', '在他眼里，她是世界上最美的新娘。', 'ในสายตาเขา เธอคือเจ้าสาวที่สวยที่สุดในโลก', 'zài tā yǎn lǐ, tā shì shì jiè shàng zuì měi de xīn niáng'),
(1117, '丰', 'fēng', '丰收', 'fēng shōu', 'เก็บเกี่ยวได้มาก/ผลผลิตอุดม', '秋天是丰收的季节。', 'ฤดูใบไม้ร่วงเป็นฤดูแห่งการเก็บเกี่ยว', 'qiū tiān shì fēng shōu de jì jié'),
(1118, '克', 'kè', '克服', 'kè fú', 'เอาชนะ/ฟันฝ่า', '只要兄弟齐心，就一定能克服困难。', 'ขอเพียงพี่น้องร่วมใจกัน ก็ต้องเอาชนะอุปสรรคได้แน่', 'zhǐ yào xiōng dì qí xīn, jiù yí dìng néng kè fú kùn nán'),
(1119, '棋', 'qí', '下棋', 'xià qí', 'เล่นหมากรุก', '爷爷常常跟他的老伙伴一起下棋。', 'คุณปู่มักเล่นหมากรุกกับเพื่อนเก่าอยู่บ่อยๆ', 'yé ye cháng cháng gēn tā de lǎo huǒ bàn yì qǐ xià qí'),
(1120, '重', 'zhòng', '称重', 'chēng zhòng', 'ชั่งน้ำหนัก', '丰收时节，果农正在给水果称重。', 'ช่วงเก็บเกี่ยว ชาวสวนผลไม้กำลังชั่งน้ำหนักผลไม้', 'fēng shōu shí jié, guǒ nóng zhèng zài gěi shuǐ guǒ chēng zhòng'),
(1121, '刻', 'kè', '刻刀', 'kè dāo', 'มีดแกะสลัก', '古人用刻刀把文字刻在了竹子上。', 'คนโบราณใช้มีดแกะสลักจารึกตัวอักษรลงบนไม้ไผ่', 'gǔ rén yòng kè dāo bǎ wén zì kè zài le zhú zi shàng'),
(1122, '导', 'dǎo', '导弹', 'dǎo dàn', 'ขีปนาวุธ', '这种导弹的破坏力非常大。', 'ขีปนาวุธชนิดนี้มีอานุภาพทำลายล้างสูงมาก', 'zhè zhǒng dǎo dàn de pò huài lì fēi cháng dà'),
(1123, '缸', 'gāng', '水缸', 'shuǐ gāng', 'โอ่งน้ำ', '小老鼠不小心掉到了一口水缸里。', 'หนูน้อยพลัดตกลงไปในโอ่งน้ำใบหนึ่ง', 'xiǎo lǎo shǔ bù xiǎo xīn diào dào le yì kǒu shuǐ gāng lǐ'),
(1124, '断', 'duàn', '割断', 'gē duàn', 'ตัดขาด', '串珠被割断了，珠子滚落了一地。', 'สายลูกปัดถูกตัดขาด ลูกปัดกลิ้งหล่นเกลื่อนพื้น', 'chuàn zhū bèi gē duàn le, zhū zi gǔn luò le yí dì'),
(1125, '脆', 'cuì', '酥脆', 'sū cuì', 'กรอบ', '奶奶最喜欢吃酥脆的小点心了。', 'คุณย่าชอบกินขนมกรอบๆ ชิ้นเล็กๆ ที่สุด', 'nǎi nai zuì xǐ huān chī sū cuì de xiǎo diǎn xīn le'),
(1126, '折', 'zhé', '折断', 'zhé duàn', 'หักออก', '这把新尺子被我不小心折断。', 'ไม้บรรทัดอันใหม่นี้ฉันเผลอทำหักไป', 'zhè bǎ xīn chǐ zi bèi wǒ bù xiǎo xīn zhé duàn'),
(1127, '斤', 'jīn', '几斤', 'jǐ jīn', 'กี่ชั่ง (หน่วยน้ำหนัก)', '爷爷今天买了好几斤水果。', 'วันนี้คุณปู่ซื้อผลไม้มาหลายชั่ง', 'yé ye jīn tiān mǎi le hǎo jǐ jīn shuǐ guǒ'),
(1128, '革', 'gé', '皮革', 'pí gé', 'หนัง (สัตว์)', '动物的皮革可以用来做很多东西。', 'หนังสัตว์สามารถนำมาทำของได้หลายอย่าง', 'dòng wù de pí gé kě yǐ yòng lái zuò hěn duō dōng xi'),
(1129, '单', 'dān', '孤单', 'gū dān', 'โดดเดี่ยว/เดียวดาย', '一个稻草人孤单地站在稻田里。', 'หุ่นไล่กายืนอยู่อย่างโดดเดี่ยวกลางทุ่งนา', 'yí gè dào cǎo rén gū dān de zhàn zài dào tián lǐ'),
(1130, '挑', 'tiāo', '挑选', 'tiāo xuǎn', 'เลือก/คัดเลือก', '他精心挑选了几只肥羊送给了朋友。', 'เขาคัดเลือกแกะอ้วนๆ หลายตัวอย่างพิถีพิถันไปให้เพื่อน', 'tā jīng xīn tiāo xuǎn le jǐ zhī féi yáng sòng gěi le péng yǒu'),
(1131, '唤', 'huàn', '呼唤', 'hū huàn', 'เรียกหา/ร้องเรียก', '他在梦中不停地呼唤一个人的名字。', 'ในฝันเขาเรียกชื่อของคนคนหนึ่งไม่หยุด', 'tā zài mèng zhōng bù tíng de hū huàn yí gè rén de míng zi'),
(1132, '帜', 'zhì', '旗帜', 'qí zhì', 'ธง/ธงชัย', '这面旗帜指引着我们前进的道路。', 'ธงผืนนี้ชี้นำเส้นทางเดินหน้าของเรา', 'zhè miàn qí zhì zhǐ yǐn zhe wǒ men qián jìn de dào lù'),
(1133, '托', 'tuō', '托起', 'tuō qǐ', 'ยกชู/ประคองขึ้น', '爸爸伸出双手把孩子高高托起。', 'พ่อยื่นสองมือออกมาชูลูกขึ้นสูงๆ', 'bà ba shēn chū shuāng shǒu bǎ hái zi gāo gāo tuō qǐ'),
(1134, '卖', 'mài', '卖出', 'mài chū', 'ขายออก', '今天老板卖出了二十多件衣服。', 'วันนี้เถ้าแก่ขายเสื้อผ้าออกไปยี่สิบกว่าตัว', 'jīn tiān lǎo bǎn mài chū le èr shí duō jiàn yī fú'),
(1135, '胡', 'hú', '胡乱', 'hú luàn', 'มั่วซั่ว/ส่งเดช', '小孩子在外面不要胡乱讲话。', 'เด็กๆ อยู่ข้างนอกอย่าพูดจาส่งเดช', 'xiǎo hái zi zài wài miàn bú yào hú luàn jiǎng huà'),
(1136, '钉', 'dīng', '钉子', 'dīng zi', 'ตะปู', '木板上有个尖尖的钉子冒出了头。', 'บนแผ่นไม้มีตะปูแหลมโผล่หัวออกมาตัวหนึ่ง', 'mù bǎn shàng yǒu gè jiān jiān de dīng zi mào chū le tóu'),
(1137, '节', 'jié', '节省', 'jié shěng', 'ประหยัด', '为了节省时间，我们打算坐飞机。', 'เพื่อประหยัดเวลา เราตั้งใจจะนั่งเครื่องบิน', 'wèi le jié shěng shí jiān, wǒ men dǎ suàn zuò fēi jī'),
(1138, '伟', 'wěi', '伟大', 'wěi dà', 'ยิ่งใหญ่', '诗人用诗歌赞美自己伟大的祖国。', 'กวีใช้บทกวีสรรเสริญมาตุภูมิอันยิ่งใหญ่ของตน', 'shī rén yòng shī gē zàn měi zì jǐ wěi dà de zǔ guó'),
(1139, '尤', 'yóu', '尤其', 'yóu qí', 'โดยเฉพาะ', '我喜欢甜品，尤其是奶油蛋糕。', 'ฉันชอบของหวาน โดยเฉพาะเค้กครีม', 'wǒ xǐ huān tián pǐn, yóu qí shì nǎi yóu dàn gāo'),
(1140, '创', 'chuàng', '创造', 'chuàng zào', 'สร้างสรรค์/ประดิษฐ์', '哥哥很聪明，有很多发明创造。', 'พี่ชายฉลาดมาก มีสิ่งประดิษฐ์สร้างสรรค์มากมาย', 'gē ge hěn cōng míng, yǒu hěn duō fā míng chuàng zào'),
(1141, '区', 'qū', '区域', 'qū yù', 'เขตพื้นที่/บริเวณ', '这些植物是这片区域特有的。', 'พืชพวกนี้เป็นพืชเฉพาะถิ่นของพื้นที่บริเวณนี้', 'zhè xiē zhí wù shì zhè piàn qū yù tè yǒu de'),
(1142, '层', 'céng', '楼层', 'lóu céng', 'ชั้น (ของอาคาร)', '一座楼，楼层高，白云飘在半中腰。', 'ตึกหลังหนึ่ง ชั้นสูงลิ่ว เมฆขาวลอยอยู่แค่ครึ่งตึก', 'yí zuò lóu, lóu céng gāo, bái yún piāo zài bàn zhōng yāo'),
(1143, '丹', 'dān', '丹药', 'dān yào', 'ยาวิเศษ/ยาอายุวัฒนะ', '没有什么丹药可以让人长生不老。', 'ไม่มียาวิเศษใดที่ทำให้คนเป็นอมตะไม่แก่ได้', 'méi yǒu shén me dān yào kě yǐ ràng rén cháng shēng bù lǎo'),
(1144, '州', 'zhōu', '神州', 'shén zhōu', 'เสินโจว (แผ่นดินจีน)', '神州大地，山河秀美，令人神往。', 'แผ่นดินเสินโจว ภูเขาสายน้ำงดงาม ชวนให้ใฝ่ฝันถึง', 'shén zhōu dà dì, shān hé xiù měi, lìng rén shén wǎng'),
(1145, '郊', 'jiāo', '郊区', 'jiāo qū', 'ชานเมือง', '越来越多的人搬到郊区去住了。', 'ผู้คนย้ายไปอยู่ชานเมืองกันมากขึ้นเรื่อยๆ', 'yuè lái yuè duō de rén bān dào jiāo qū qù zhù le'),
(1146, '激', 'jī', '激动', 'jī dòng', 'ตื่นเต้น/ตื้นตัน', '游乐场到处都是人们激动的叫喊声。', 'ในสวนสนุกเต็มไปด้วยเสียงร้องอันตื่นเต้นของผู้คน', 'yóu lè chǎng dào chù dōu shì rén men jī dòng de jiào hǎn shēng'),
(1147, '斜', 'xié', '倾斜', 'qīng xié', 'เอียง/ลาดเอียง', '车子急转弯时身体会跟着倾斜。', 'ตอนรถเลี้ยวหักศอก ตัวเราก็จะเอียงตามไปด้วย', 'chē zi jí zhuǎn wān shí shēn tǐ huì gēn zhe qīng xié'),
(1148, '抽', 'chōu', '抽水', 'chōu shuǐ', 'สูบน้ำ', '抽水机把田里的雨水抽出来了。', 'เครื่องสูบน้ำสูบน้ำฝนออกจากนาไปแล้ว', 'chōu shuǐ jī bǎ tián lǐ de yǔ shuǐ chōu chū lái le'),
(1149, '嫌', 'xián', '嫌弃', 'xián qì', 'รังเกียจ', '小女孩嫌弃自己手里的野草太丑了。', 'เด็กหญิงตัวน้อยรังเกียจว่าหญ้าในมือตัวเองน่าเกลียดเกินไป', 'xiǎo nǚ hái xián qì zì jǐ shǒu lǐ de yě cǎo tài chǒu le'),
(1150, '懒', 'lǎn', '懒洋洋', 'lǎn yáng yáng', 'เอื่อยเฉื่อย/ขี้เกียจตัวเป็นขน', '一只树懒正懒洋洋地趴在树枝上。', 'สลอธตัวหนึ่งกำลังนอนหมอบอย่างเอื่อยเฉื่อยอยู่บนกิ่งไม้', 'yì zhī shù lǎn zhèng lǎn yáng yáng de pā zài shù zhī shàng');
